import numpy as np
A=np.array([[0,0,3,0],[2,0,3,4],[2,1,1,0],[2,0,0,4]])
B=np.array([[2,2,2],[0,1,0],[0,1,3],[4,0,4]])
for k in range(4):
 for fl in (False,True):
  X=np.rot90(A,k)
  if fl:X=np.fliplr(X)
  for i in range(X.shape[0]-3+1):
   for j in range(X.shape[1]-3+1):
    Y=X[i:i+4,j:j+3]
    if np.array_equal(Y,B):print('exact',k,fl,i,j)
    # compare at nonzero positions, matching zeros too
    print('',end='')
  # best metrics over cropped windows with arbitrary size crop
  best=(999,None)
  for i in range(X.shape[0]-3+1):
   for j in range(X.shape[1]-3+1):
    Y=X[i:i+4,j:j+3]
    d=np.count_nonzero(Y!=B)
    if d<best[0]:best=(d,(i,j,Y.tolist()))
  print(k,fl,best)

